IF EXISTS (
    SELECT 1 FROM @Tep f WHERE (
        SELECT COUNT(*) FROM dbo.Sach s JOIN dbo.Chuong c ON c.MaSach=s.MaSach
        WHERE s.TenSach=f.TenSach AND s.TacGia=f.TacGia
          AND c.SoChuong=f.SoChuong AND c.TieuDe=f.TieuDe
    ) <> 1
)
    THROW 50311, N'Chưa có đủ 48 truyện / 288 chương khớp bộ mẫu, hoặc có tên trùng. Không thay đổi dữ liệu.', 1;
DECLARE @DaThem int;
INSERT dbo.NoiDungChuong(MaChuong,ThuTu,DuongDanTep,KieuTep,TenTepGoc,DungLuong)
SELECT c.MaChuong,f.ThuTu,f.DuongDanTep,f.KieuTep,f.TenTepGoc,f.DungLuong
FROM @Tep f JOIN dbo.Sach s ON s.TenSach=f.TenSach AND s.TacGia=f.TacGia
JOIN dbo.Chuong c ON c.MaSach=s.MaSach AND c.SoChuong=f.SoChuong AND c.TieuDe=f.TieuDe
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.NoiDungChuong n WITH(UPDLOCK,HOLDLOCK)
    WHERE (n.MaChuong=c.MaChuong AND n.ThuTu=f.ThuTu) OR n.DuongDanTep=f.DuongDanTep
);
SET @DaThem=@@ROWCOUNT;
COMMIT TRANSACTION;
SELECT @DaThem AS SoTepDaBoSung;
END TRY
BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
GO
